solution:
// Return a longest strictly increasing subsequence of nums.
// A subsequence keeps the original order of the elements it takes but may
// skip any of them; strictly increasing means every element is greater than
// the one before it, so equal values never both appear.
// When several longest strictly increasing subsequences exist, return the
// one whose list of values is lexicographically smallest (compare the first
// values, then the second values, and so on). Return [] for an empty list.
// Values may be negative and may be as large as the Int range allows; do not
// rely on sentinel values.
// Examples:
//   longest_increasing_subsequence([3, 1, 2, 1, 8, 5, 6]) == [1, 2, 5, 6]
//   longest_increasing_subsequence([5, 4, 3]) == [3]
fn longest_increasing_subsequence(nums: List[Int]) -> List[Int] {
  let n = len(nums);
  if n == 0 {
    return [];
  }
  let best = lengths_from(nums);
  let mut need = unwrap_or(max_of(best), 0);
  let mut out: List[Int] = [];
  let mut start = 0;
  let mut prev: Option[Int] = None;
  while need > 0 {
    // among positions that can start the rest, take the smallest value,
    // and its earliest position, which leaves the most choices afterwards
    let mut pick = -1;
    for j in range(start, n) {
      let above = match prev {
        Some(p) => nums[j] > p,
        None => true,
      };
      if best[j] == need && above && (pick == -1 || nums[j] < nums[pick]) {
        pick = j;
      }
    }
    out = push(out, nums[pick]);
    prev = Some(nums[pick]);
    start = pick + 1;
    need = need - 1;
  }
  out
}

// best[i]: length of the longest strictly increasing subsequence starting at i.
fn lengths_from(nums: List[Int]) -> List[Int] {
  let n = len(nums);
  // built from i = n - 1 down to 0, so best[j] is rev[n - 1 - j]
  let mut rev: List[Int] = [];
  let mut i = n - 1;
  while i >= 0 {
    let mut b = 1;
    for j in range(i + 1, n) {
      let bj = rev[n - 1 - j];
      if nums[j] > nums[i] && bj + 1 > b {
        b = bj + 1;
      }
    }
    rev = push(rev, b);
    i = i - 1;
  }
  reverse(rev)
}
